function validate([operations, args]) {
  if (!Array.isArray(operations) || !Array.isArray(args) || operations.length !== args.length) return 'operations and arguments need the same length.';
  if (operations[0] !== 'FindSumPairs' || !Array.isArray(args[0]) || args[0].length !== 2) return 'Start with FindSumPairs(nums1, nums2).';
  const [nums1, nums2] = args[0];
  if (!Array.isArray(nums1) || nums1.length < 1 || nums1.length > 1000) return 'nums1 needs 1 to 1000 values.';
  if (!Array.isArray(nums2) || nums2.length < 1 || nums2.length > 100000) return 'nums2 needs 1 to 10^5 values.';
  if (nums1.some(v => !Number.isInteger(v) || v < 1 || v > 1000000000)) return 'Each nums1 value is between 1 and 10^9.';
  if (nums2.some(v => !Number.isInteger(v) || v < 1 || v > 100000)) return 'Each starting nums2 value is between 1 and 10^5.';
  let adds = 0;
  let counts = 0;
  for (let i = 1; i < operations.length; i++) {
    const a = args[i];
    if (!Array.isArray(a)) return 'Each call needs an argument list.';
    if (operations[i] === 'add') {
      adds++;
      if (a.length !== 2 || !Number.isInteger(a[0]) || a[0] < 0 || a[0] >= nums2.length) return 'add needs an index from 0 to nums2.length - 1.';
      if (!Number.isInteger(a[1]) || a[1] < 1 || a[1] > 100000) return 'add values are between 1 and 10^5.';
    } else if (operations[i] === 'count') {
      counts++;
      if (a.length !== 1 || !Number.isInteger(a[0]) || a[0] < 1 || a[0] > 1000000000) return 'count needs a tot between 1 and 10^9.';
    } else {
      return 'Only add and count can follow the constructor.';
    }
  }
  if (adds > 1000 || counts > 1000) return 'At most 1000 calls to add and 1000 to count.';
  return null;
}

