class FindSumPairs {
  constructor(nums1, nums2) {
    this.nums1 = nums1;
    this.nums2 = [...nums2];
    this.freq = new Map();
    for (const value of this.nums2) {
      this.freq.set(value, (this.freq.get(value) || 0) + 1);
    }
  }

  add(index, val) {
    const old = this.nums2[index];
    const updated = old + val;
    this.freq.set(old, this.freq.get(old) - 1);
    this.freq.set(updated, (this.freq.get(updated) || 0) + 1);
    this.nums2[index] = updated;
  }

  count(tot) {
    let pairs = 0;
    for (const value of this.nums1) {
      pairs += this.freq.get(tot - value) || 0;
    }
    return pairs;
  }
}

