    this.a = nums1.slice();
    this.b = nums2.slice();
  }
  add(index, val) {
    this.b[index] += val;
  }
  count(tot) {
    let total = 0;
    for (const x of this.a) for (const y of this.b) if (x + y === tot) total++;
