  const n2 = large ? (rand() < 0.6 ? 2000 : int(1, 2000)) : int(1, 6);
  const wide = rand() < 0.3;
  const top1 = wide ? 1000000000 : (large ? 50 : 6);
  const top2 = wide ? 100000 : (large ? 50 : 6);
  const nums1 = Array.from({ length: n1 }, () => int(1, top1));
  const nums2 = Array.from({ length: n2 }, () => int(1, top2));
  const current = nums2.slice();
  const calls = large ? 499 : int(1, 12);
  const addRate = 0.2 + rand() * 0.5;
  const topVal = wide ? 100000 : (large ? 20 : 3);
  const operations = ['FindSumPairs'];
  const args = [[nums1, nums2]];
  for (let k = 0; k < calls; k++) {
    if (rand() < addRate) {
      const index = int(0, n2 - 1);
      const val = int(1, topVal);
      current[index] += val;
      operations.push('add');
      args.push([index, val]);
    } else {
      let tot = rand() < 0.75 ? nums1[int(0, n1 - 1)] + current[int(0, n2 - 1)] : int(1, top1 + top2);
